 const headers=header.map((c,n)=>{const v=String(b2Value(c));return v.length<=120&&!/[{}\[\]\r\n]/.test(v)?v:b2Column(n);}),statusColumns=headers.flatMap((h,i)=>h==='status'?[i]:[]);
